/**
 * Entry point. Mounts Request Builders on operation pages, the Request
 * Playground, and the operation finder.
 *
 * All data URLs are resolved relative to this module's own URL, so the site
 * works at a domain root, under a GitHub Pages project path, or locally.
 * The only fetches are same-origin static files generated by the site build.
 */

import { mountRequestBuilder } from "./ui.js";

// This file lives at <site root>/assets/request-builder/index.js.
export const SITE_ROOT = new URL("../../", import.meta.url);

let siteIndexPromise = null;

export function siteUrl(path) {
  return new URL(path, SITE_ROOT).href;
}

async function fetchJson(path) {
  const response = await fetch(siteUrl(path), { credentials: "same-origin" });
  if (!response.ok) throw new Error(`Failed to load ${path} (${response.status})`);
  return response.json();
}

export function loadSiteIndex() {
  siteIndexPromise ||= fetchJson("assets/data/site-index.json");
  return siteIndexPromise;
}

function modelUrlFor(siteIndex, section) {
  const models = siteIndex.models[section] || {};
  return (name) => (models[name] ? siteUrl(models[name]) : null);
}

/** Case-insensitive match of every query term against an operation's metadata. */
export function matchOperations(siteIndex, query) {
  const titles = Object.fromEntries(siteIndex.sections.map((section) => [section.id, section.title]));
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  return siteIndex.operations.filter((operation) => {
    const haystack = `${operation.title} ${operation.operationId} ${operation.method} ${operation.path} ${operation.tag} ${titles[operation.section]}`.toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
}

function renderError(container, message) {
  const paragraph = document.createElement("p");
  paragraph.className = "rb-load-error";
  paragraph.textContent = message;
  container.replaceChildren(paragraph);
}

export async function mountOperation(container, operationId, options = {}) {
  const siteIndex = await loadSiteIndex();
  const entry = siteIndex.operations.find((operation) => operation.id === operationId);
  if (!entry) throw new Error(`Unknown operation: ${operationId}`);
  const document = await fetchJson(entry.json);
  return mountRequestBuilder(container, document, { ...options, modelUrl: modelUrlFor(siteIndex, entry.section) });
}

// --- operation pages --------------------------------------------------------

async function mountOperationPages() {
  for (const container of document.querySelectorAll("[data-request-builder]")) {
    try {
      await mountOperation(container, container.dataset.requestBuilder);
    } catch (error) {
      renderError(container, `The Request Builder could not be loaded: ${error.message}`);
    }
  }
}

// --- playground -------------------------------------------------------------

function operationLabel(operation) {
  return `${operation.method} ${operation.path} — ${operation.title}`;
}

async function mountPlayground(container) {
  const siteIndex = await loadSiteIndex();
  const sectionTitles = Object.fromEntries(siteIndex.sections.map((section) => [section.id, section.title]));

  const filterId = "playground-filter";
  const selectId = "playground-operation";
  const filter = Object.assign(document.createElement("input"), {
    id: filterId, type: "search", className: "rb-input", placeholder: "Filter by name, path or operation ID", autocomplete: "off",
  });
  const select = Object.assign(document.createElement("select"), { id: selectId, className: "rb-input" });
  const count = Object.assign(document.createElement("p"), { className: "rb-field__help" });
  count.setAttribute("aria-live", "polite");
  const docsLink = document.createElement("p");
  const builder = document.createElement("div");

  const labelFor = (id, text) => Object.assign(document.createElement("label"), { htmlFor: id, className: "rb-field__label", textContent: text });
  const controls = document.createElement("div");
  controls.className = "playground__controls";
  controls.append(labelFor(filterId, "Filter operations"), filter, labelFor(selectId, "Operation"), select, count, docsLink);
  container.replaceChildren(controls, builder);

  let currentId = null;

  function populate(query) {
    const matches = matchOperations(siteIndex, query);
    select.replaceChildren();
    const groups = new Map();
    for (const operation of matches) {
      const label = `${sectionTitles[operation.section]} · ${operation.tag}`;
      if (!groups.has(label)) {
        const optgroup = document.createElement("optgroup");
        optgroup.label = label;
        groups.set(label, optgroup);
        select.append(optgroup);
      }
      groups.get(label).append(new Option(operationLabel(operation), operation.id));
    }
    count.textContent = `${matches.length} of ${siteIndex.operations.length} operations`;
    if (matches.some((operation) => operation.id === currentId)) select.value = currentId;
    return matches;
  }

  async function load(id) {
    const entry = siteIndex.operations.find((operation) => operation.id === id);
    if (!entry || id === currentId) return;
    currentId = id;
    select.value = id;
    const link = document.createElement("a");
    link.href = siteUrl(entry.page);
    link.textContent = `Read the ${entry.title} reference`;
    docsLink.replaceChildren(link);
    if (window.location.hash.slice(1) !== id) history.replaceState(null, "", `#${id}`);
    try {
      await mountOperation(builder, id, { title: entry.title });
    } catch (error) {
      renderError(builder, `The operation could not be loaded: ${error.message}`);
    }
  }

  filter.addEventListener("input", () => {
    const matches = populate(filter.value);
    if (matches.length && !matches.some((operation) => operation.id === currentId)) load(matches[0].id);
  });
  select.addEventListener("change", () => load(select.value));
  window.addEventListener("hashchange", () => load(window.location.hash.slice(1)));

  populate("");
  const requested = decodeURIComponent(window.location.hash.slice(1));
  const initial = siteIndex.operations.some((operation) => operation.id === requested)
    ? requested
    : container.dataset.requestPlayground || siteIndex.operations[0].id;
  await load(initial);
}

// --- operation finder -------------------------------------------------------

const FINDER_LIMIT = 50;

async function mountFinder(container) {
  const siteIndex = await loadSiteIndex();
  const sectionTitles = Object.fromEntries(siteIndex.sections.map((section) => [section.id, section.title]));
  const input = Object.assign(document.createElement("input"), {
    id: "finder-query", type: "search", className: "rb-input", autocomplete: "off",
    placeholder: "getLeadById, /rest/v1/leads.json, bulk import…",
  });
  const label = Object.assign(document.createElement("label"), { htmlFor: "finder-query", className: "rb-field__label", textContent: "Find an operation" });
  const status = Object.assign(document.createElement("p"), { className: "rb-field__help" });
  status.setAttribute("aria-live", "polite");
  const list = Object.assign(document.createElement("ul"), { className: "finder__results" });
  container.replaceChildren(label, input, status, list);

  function render() {
    const hasQuery = input.value.trim() !== "";
    const matches = hasQuery ? matchOperations(siteIndex, input.value) : [];
    list.replaceChildren(...matches.slice(0, FINDER_LIMIT).map((operation) => {
      const item = document.createElement("li");
      const link = Object.assign(document.createElement("a"), { href: siteUrl(operation.page), className: "finder__link" });
      const method = Object.assign(document.createElement("span"), {
        className: `http-method http-method--${operation.method.toLowerCase()}`, textContent: operation.method,
      });
      const title = Object.assign(document.createElement("span"), { className: "finder__title", textContent: operation.title });
      const path = Object.assign(document.createElement("code"), { className: "finder__path", textContent: operation.path });
      const meta = Object.assign(document.createElement("span"), {
        className: "finder__meta", textContent: `${sectionTitles[operation.section]} · ${operation.tag} · ${operation.operationId}`,
      });
      link.append(method, title, path, meta);
      item.append(link);
      return item;
    }));
    status.textContent = hasQuery
      ? `${matches.length} matching ${matches.length === 1 ? "operation" : "operations"}${matches.length > FINDER_LIMIT ? `, showing the first ${FINDER_LIMIT}` : ""}.`
      : `Type to search ${siteIndex.operations.length} operations.`;
  }

  input.addEventListener("input", render);
  const initial = new URLSearchParams(window.location.search).get("q");
  if (initial) input.value = initial;
  render();
}

async function main() {
  await Promise.all([
    mountOperationPages(),
    ...[...document.querySelectorAll("[data-request-playground]")].map((container) =>
      mountPlayground(container).catch((error) => renderError(container, `The playground could not be loaded: ${error.message}`))),
    ...[...document.querySelectorAll("[data-operation-finder]")].map((container) =>
      mountFinder(container).catch((error) => renderError(container, `The operation finder could not be loaded: ${error.message}`))),
  ]);
}

main();
